const html = ($input.first().json.data || $input.first().json.body || '').toString();
let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ')
  .trim();
// Claude has a context limit; a guideline blog post shouldn't need more than this.
text = text.slice(0, 60000);

const prep = $('Prepare Data').first().json;
return [{ json: { ...prep, page_text: text } }];

